import os
from typing import Any, Dict, Optional
from urllib.parse import urlencode

import requests


class Auth0FederatedProfileFetcher:
    def __init__(
        self,
        domain: Optional[str] = None,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        audience: Optional[str] = None,
    ) -> None:
        self.domain = (domain or os.getenv("AUTH0_DOMAIN", "")).strip()
        self.client_id = (client_id or os.getenv("AUTH0_CLIENT_ID", "")).strip()
        self.client_secret = (client_secret or os.getenv("AUTH0_CLIENT_SECRET", "")).strip()
        self.audience = (audience or os.getenv("AUTH0_AUDIENCE", "")).strip()

        if not self.domain:
            raise ValueError("Missing Auth0 domain. Set AUTH0_DOMAIN.")
        if not self.client_id:
            raise ValueError("Missing Auth0 client id. Set AUTH0_CLIENT_ID.")

        self.issuer_base = f"https://{self.domain}"
        self.token_url = f"{self.issuer_base}/oauth/token"
        self.userinfo_url = f"{self.issuer_base}/userinfo"

    def get_authorization_url(
        self,
        redirect_uri: str,
        scope: str = "openid profile email",
        state: Optional[str] = None,
        connection: Optional[str] = None,
        prompt: Optional[str] = None,
    ) -> str:
        params: Dict[str, Any] = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": redirect_uri,
            "scope": scope,
        }
        if state:
            params["state"] = state
        if connection:
            params["connection"] = connection
        if prompt:
            params["prompt"] = prompt
        return f"{self.issuer_base}/authorize?{urlencode(params)}"

    def exchange_code_for_tokens(
        self,
        code: str,
        redirect_uri: str,
    ) -> Dict[str, Any]:
        payload: Dict[str, Any] = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": redirect_uri,
        }
        if self.client_secret:
            payload["client_secret"] = self.client_secret

        if self.audience:
            payload["audience"] = self.audience

        resp = requests.post(
            self.token_url,
            json=payload,
            timeout=30,
            headers={"Content-Type": "application/json"},
        )
        resp.raise_for_status()
        return resp.json()

    def fetch_userinfo(self, access_token: str) -> Dict[str, Any]:
        resp = requests.get(
            self.userinfo_url,
            timeout=30,
            headers={"Authorization": f"Bearer {access_token}"},
        )
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def normalize_claims(claims: Dict[str, Any]) -> Dict[str, Any]:
        normalized: Dict[str, Any] = {}

        subject = claims.get("sub") or claims.get("user_id") or claims.get("id")
        if subject is not None:
            normalized["subject"] = subject

        name = claims.get("name") or claims.get("nickname") or claims.get("preferred_username")
        if name is not None:
            normalized["display_name"] = name

        email = claims.get("email")
        if email is not None:
            normalized["email"] = email

        email_verified = claims.get("email_verified")
        if email_verified is not None:
            normalized["email_verified"] = bool(email_verified)

        picture = claims.get("picture") or claims.get("avatar_url") or claims.get("profile_picture")
        if picture is not None:
            normalized["avatar_url"] = picture

        given_name = claims.get("given_name")
        if given_name is not None:
            normalized["given_name"] = given_name

        family_name = claims.get("family_name")
        if family_name is not None:
            normalized["family_name"] = family_name

        locale = claims.get("locale")
        if locale is not None:
            normalized["locale"] = locale

        issuer = claims.get("iss")
        if issuer is not None:
            normalized["issuer"] = issuer

        if "iat" in claims:
            normalized["issued_at"] = claims["iat"]
        if "exp" in claims:
            normalized["expires_at"] = claims["exp"]

        roles = claims.get("roles") or claims.get("role") or claims.get("groups")
        if roles is not None:
            if isinstance(roles, str):
                normalized["roles"] = [roles]
            elif isinstance(roles, (list, tuple, set)):
                normalized["roles"] = list(roles)

        raw_extra = {}
        standard_keys = {
            "sub",
            "user_id",
            "id",
            "name",
            "nickname",
            "preferred_username",
            "email",
            "email_verified",
            "picture",
            "avatar_url",
            "profile_picture",
            "given_name",
            "family_name",
            "locale",
            "iss",
            "iat",
            "exp",
            "roles",
            "role",
            "groups",
        }
        for key, value in claims.items():
            if key not in standard_keys:
                raw_extra[key] = value
        if raw_extra:
            normalized["claims"] = raw_extra

        return normalized

    def fetch_and_normalize_profile(
        self,
        access_token: str,
    ) -> Dict[str, Any]:
        claims = self.fetch_userinfo(access_token)
        return self.normalize_claims(claims)


def fetch_and_normalize_federated_user_profile(
    access_token: str,
    domain: Optional[str] = None,
    client_id: Optional[str] = None,
    client_secret: Optional[str] = None,
    audience: Optional[str] = None,
) -> Dict[str, Any]:
    return Auth0FederatedProfileFetcher(
        domain=domain,
        client_id=client_id,
        client_secret=client_secret,
        audience=audience,
    ).fetch_and_normalize_profile(access_token)
